// Cloudflare entry point: the OpenNext (Next.js) app, plus Hot Comet's Durable Objects and WebSocket route.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as nextHandler } from "../.open-next/worker.js";
import { ticketSecret, verifyTicket } from "../src/party/ticket";
import { PartyLobby, PartyRoom, type PartyEnv } from "./party-do";

export { PartyLobby, PartyRoom };

export default {
  async fetch(req: Request, env: PartyEnv & Record<string, unknown>, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(req.url);
    const m = url.pathname.match(/^\/party-ws\/([A-Z]{4})$/);
    if (m) {
      const secret = ticketSecret(env);
      const t = secret ? await verifyTicket(url.searchParams.get("t"), secret) : null;
      if (!t || t.c !== m[1]) return new Response("Unauthorized", { status: 401 });
      const stub = env.PARTY_ROOM.get(env.PARTY_ROOM.idFromName(m[1]));
      const target = new URL("https://room/ws");
      target.searchParams.set("u", t.u);
      target.searchParams.set("n", t.n);
      return stub.fetch(new Request(target.toString(), req));
    }
    return nextHandler.fetch(req, env, ctx);
  },
} satisfies ExportedHandler<PartyEnv & Record<string, unknown>>;
